document.querySelector("#batch40 .grid").insertAdjacentHTML("beforeend","<a class=\"card\" href=\"summaries/mahmoud-linefire.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف على خط النار\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>على خط النار</h3><p>يدعو المقتطف المنشور لدى أسفار إلى عدم تلقي الأفكار والإعلام بلا فحص. يستخدم مصطفى محمود صورا حادة عن التسميم والفخاخ ليشدد على ضرورة الانتباه إل…</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-edgequake.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف على حافة الزلزال\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>على حافة الزلزال</h3><p>يثبت مصدر الطبعة على حافة الزلزال عملا مستقلا لمصطفى محمود ضمن المقالات والفكر السياسي، في إصدار لمكتبة مصر. وهو غير مسرحية الزلزال للمؤلف نفسه، …</p><small>مصطفى محمود</small></a><a class=\"card\" href=\"summaries/mahmoud-fire.html\"><div class=\"book-art real-cover\"><img src=\"data:image/webp;base64,\" alt=\"غلاف نار تحت الرماد\" width=\"270\" height=\"360\" loading=\"lazy\"></div><span class=\"tag\">مرجع طبعة تجارية</span><h3>نار تحت الرماد</h3><p>تثبت صفحة أسفار نار تحت الرماد لمصطفى محمود في طبعة مكتبة مصر، وتضعه في المقالات والنثر والفكر الإسلامي. لكنها لا تتيح في المادة التي فحصناها فهر…</p><small>مصطفى محمود</small></a>");
